from collections import OrderedDict

def to_key_val_list(value):
    if isinstance(value, dict):
        return value.items()
    return value

def merge_setting(request_setting, session_setting, dict_class=OrderedDict):
    if session_setting is None:
        return request_setting
    if request_setting is None:
        return session_setting
    if not (isinstance(session_setting, dict) and isinstance(request_setting, dict)):
        return request_setting

    merged_setting = dict_class(to_key_val_list(session_setting))
    merged_setting.update(to_key_val_list(request_setting))

    # Remove keys that are set to None.
    none_keys = [k for (k, v) in merged_setting.items() if v is None]
    for key in none_keys:
        del merged_setting[key]

    return merged_setting

# Test 1: Session header set to None
session_headers = {
    'User-Agent': 'python-requests/2.31.0',
    'Accept-Encoding': None,
    'Accept': '*/*',
    'Connection': 'keep-alive',
}
request_headers = {'User-Agent': 'custom'}
merged = merge_setting(request_headers, session_headers)
print('Test 1 - Session None header removed:', 'Accept-Encoding' not in merged)

# Test 2: Request header set to None (existing behavior)
session_headers2 = {
    'User-Agent': 'python-requests/2.31.0',
    'Accept-Encoding': 'gzip',
    'Accept': '*/*',
}
request_headers2 = {'Accept-Encoding': None}
merged2 = merge_setting(request_headers2, session_headers2)
print('Test 2 - Request None header removed:', 'Accept-Encoding' not in merged2)

# Test 3: Normal headers still work
session_headers3 = {
    'User-Agent': 'python-requests/2.31.0',
    'Accept-Encoding': 'gzip',
}
request_headers3 = {'Accept': 'text/html'}
merged3 = merge_setting(request_headers3, session_headers3)
print('Test 3 - Normal merge works:', merged3.get('Accept-Encoding') == 'gzip' and merged3.get('Accept') == 'text/html')
"

